    def request(self, method, session_id, suffix='', **kwargs):
        route = API + '/browsers/' + identifier(session_id) + '/replays' + suffix
        try:
            result = self.client._request(method, route,
                headers={'Authorization': 'Bearer ' + self.client.key(),
