h=pathlib.Path('.local/hermes-lab/home');b=pathlib.Path('.local/clanker-qa/batches/2026-10-12-corrected');m=json.loads((h/'slack_membership.json').read_text())
for lane,u in [('01-sign-instamart-saved-e402','U0C688SF7DZ'),('05-add-13-inch-3755','U0C6M6DMWAW')]:
 rp=next((b/'lanes'/lane).rglob('run.json'));run=json.loads(rp.read_text());root=run['roots'][0];p=m['members'][u]['profile'];c=sqlite3.connect(f'file:{h}/profiles/{p}/state.db?mode=ro',uri=True);c.row_factory=sqlite3.Row
 sess=list(c.execute("SELECT id FROM sessions WHERE source='slack' AND user_id=? AND chat_id=? AND thread_id=?",(u,root['channel'],root['ts'])))
 rows=[]
 for s in sess:rows.extend(c.execute("SELECT role,tool_name,tool_calls,content,timestamp FROM messages WHERE session_id=? AND timestamp>=? AND role IN ('tool','assistant') ORDER BY timestamp",(s['id'],run['started_at'])))
 tools=[r for r in rows if r['role']=='tool'];flags=[];failed=[]
 for r in tools:
  raw=r['content'] or '';data={}
  try:data=json.JSONDecoder().raw_decode(raw[raw.index('{'):])[0]
  except Exception:pass
  if not isinstance(data,dict):data={}
  failure=data.get('success') is False or bool(data.get('error')) or re.search(r'(?i)error:|timed out',raw)
  if re.search(r'(?i)profile_in_use|profilebusy|(?:profile|browser).{0,80}(?:currently in use|in use by another|already in use)',raw):flags.append({'tool':r['tool_name'],'flag':'profile_busy'})
  if failure and re.search(r'(?i)timeout|timed out|deadline',raw):flags.append({'tool':r['tool_name'],'flag':'timeout'})
  if failure and re.search(r'(?i)provider|kernel|upstream|\b50[234]\b|\b429\b',raw):flags.append({'tool':r['tool_name'],'flag':'provider_error'})
  if failure:
   category='tool_refusal_or_ui_error'
   for word,cat in [('covered','element_covered'),('not found','element_not_found'),('disabled','disabled'),('not allowed','not_allowed'),('unsupported','unsupported'),('sensitive','private_data_guard'),('console','console_error'),('required','missing_requirement'),('permission','permission_denied'),('read-only','read_only')]:
    if word in raw.lower():category=cat;break
   failed.append({'tool':r['tool_name'],'category':category,'utc':datetime.datetime.fromtimestamp(r['timestamp'],datetime.timezone.utc).isoformat()})
 latest=[]
 for r in tools[-8:]:
  raw=r['content'] or '';data={}
  try:data=json.JSONDecoder().raw_decode(raw[raw.index('{'):])[0]
  except Exception:pass
  latest.append({'tool':r['tool_name'],'success':data.get('success') if isinstance(data,dict) else None,'utc':datetime.datetime.fromtimestamp(r['timestamp'],datetime.timezone.utc).isoformat()})
 pending=[]
 if rows and rows[-1]['role']=='assistant':
  try:
   calls=json.loads(rows[-1]['tool_calls'] or '[]');pending=[a.get('function',{}).get('name') or a.get('name') for a in calls]
  except Exception:pass
 print(json.dumps({'run':run['id'],'exact_session_count':len(sess),'tool_results':len(tools),'latest':latest,'tool_failures':failed,'operational_flags':flags,'pending_tools':pending},separators=(',',':')))
x=json.loads((b/'telemetry-evidence.json').read_text());print(json.dumps({'telemetry_generated_at_utc':x['generated_at_utc'],'run_count':len(x['runs']),'browser_count':len(x['browsers']),'live_count':x['live_ordinary_campaign_browser_count'],'unconfirmed_inventory':x['unconfirmed_browser_inventory_count'],'safe_categories_confirmed':[{'session_id':z.get('session_id'),'confirmed':z.get('matches_expected'),'deleted':z.get('deleted')} for z in x['browsers']]},separators=(',',':')))
