import json
import re
import subprocess
import sqlite3

BASE = Path(__file__).resolve().parent
CAMPAIGN = '2026-10-12-corrected'
CLOUD = BASE.parents[2] / 'hermes-lab' / 'home' / '.clanker-cloud'
PROJECT = 'ofp3osdo37cq0d0wuohxb3oj'
TEAM = 'T0C6J1XCDE0'
TESTERS = {'yyovil': 'U0C6M6DMWAW', 'tanishq': 'U0C688SF7DZ'}
CATEGORIES = ('captcha','connection','console','control','interaction','network','page','platform','screenshot','system')
EXPECTED = {'connection','system','captcha'}
SID = re.compile(r'^[a-z0-9]{8,80}$')

def read_json(path):
    try:
        return json.loads(path.read_text())
    except (OSError, ValueError):
        return None

campaign_metadata = read_json(BASE / 'CAMPAIGN.json') or {}
if campaign_metadata.get('campaign') != CAMPAIGN:
    raise ValueError('The telemetry collector campaign identity was not confirmed.')
scenario_actors = {row['scenario']: (row.get('actor'), row.get('secondary'))
                   for row in campaign_metadata.get('rows',[]) if isinstance(row,dict) and row.get('scenario')}

# Replay ledgers are locally owned attribution evidence. Do not retain segment metadata.
scopes = {}
for path in (CLOUD / 'benchmark-capture').glob('*.json'):
    record = read_json(path) or {}
    scope = record.get('scope', {})
    if record.get('campaign') == CAMPAIGN and isinstance(scope, dict) and scope.get('team') == TEAM and SID.fullmatch(str(scope.get('session_id',''))):
        scopes[scope['session_id']] = {k: scope[k] for k in ('team','requester','channel','thread','context','session_id') if k in scope}

transfers = []
transfer_path = CLOUD.parent / '.clanker-vault' / 'requests.sqlite'
if transfer_path.exists():
    with sqlite3.connect(f'file:{transfer_path}?mode=ro', uri=True) as db:
        transfers = db.execute('SELECT owner,original_source,source FROM transfers WHERE team=?', (TEAM,)).fetchall()

runs = []
requests = {}
for path in sorted(BASE.rglob('run.json')):
    run = read_json(path) or {}
    if not run.get('id') or not run.get('scenario'):
        continue
    if scenario_actors.get(run['scenario']) != (run.get('actor'),run.get('secondary')):
        raise ValueError('A run actor differs from the corrected campaign actor map.')
    exact_roots = {(str(r.get('channel')), str(r.get('ts'))) for r in run.get('roots',[]) if isinstance(r,dict)}
    users = {TESTERS[t] for t in run.get('testers',[]) if t in TESTERS}
    for _ in range(8):
        before = set(exact_roots)
        for owner, original_raw, source_raw in transfers:
            if owner not in users or not source_raw: continue
            original, source = json.loads(original_raw), json.loads(source_raw)
            if (original.get('chat_id'), original.get('thread_id')) in exact_roots:
                channel, thread = source.get('chat_id'), source.get('thread_id')
                if isinstance(channel,str) and isinstance(thread,str) and re.fullmatch(r'\d+\.\d+',thread):
                    exact_roots.add((channel,thread))
        if before == exact_roots: break
    rows = []
    meta_file = path.parent / 'kernel_sessions.jsonl'
    if meta_file.exists():
        for line in meta_file.read_text().splitlines():
            try: rows.append(json.loads(line))
            except ValueError: pass
    evidence = read_json(path.parent / 'evidence' / 'kernel.json') or {}
    rows.extend(s.get('meta',{}) for s in evidence.get('sessions',[]) if isinstance(s,dict))
    accepted = {}
    for meta in rows:
        if not isinstance(meta,dict) or meta.get('match') != 'thread' or meta.get('requester') not in users:
            continue
        session_id = str(meta.get('session_id',''))
        if not SID.fullmatch(session_id):
