    assert len(campaign['rows']) == 12 and all(r['state'] == 'finished' for r in campaign['rows']), 'Final audit requires all twelve closed runs'
DB_PATHS = [p for p in [LAB / 'state.db', *sorted(LAB.glob('profiles/*/state.db'))] if p.is_file()]

def readonly(path):
    db = sqlite3.connect(f'file:{path}?mode=ro', uri=True)
    db.row_factory = sqlite3.Row
    return db

broker = readonly(LAB / '.clanker-vault/requests.sqlite')
transfers = broker.execute('SELECT owner,original_source,source FROM transfers WHERE team=?', (TEAM,)).fetchall()

def outcome(content):
    try:
        value = json.JSONDecoder().raw_decode(content[content.index('{'):])[0]
        return value if isinstance(value, dict) else None
    except (ValueError, TypeError):
        return None

def flatten(value):
    if isinstance(value, dict):
        return ' '.join(flatten(x) for x in value.values())
    if isinstance(value, list):
        return ' '.join(flatten(x) for x in value)
    return str(value) if value is not None else ''

def error_text(value, raw):
    if value is None:
        # A typed exception outside a JSON outcome is a possible tool failure.
        return raw if re.search(r'ProfileBusy|ReadTimeout|ConnectTimeout|TimeoutError|Traceback', raw) else ''
    parts = [value[k] for k in ('error', 'errors', 'exception', 'exception_type') if value.get(k)]
    failed = value.get('success') is False or value.get('status') in {'failed', 'error', 'blocked', 'expired', 'timeout'}
    if failed:
        parts += [value[k] for k in ('message', 'reason', 'code', 'failure_kind', 'provider_error') if value.get(k)]
    if value.get('exit_code') not in (None, 0):
        parts += [value[k] for k in ('output', 'stderr') if value.get(k)]
    return flatten(parts)

def linked_diagnostics(profile, references):
    found = {}
    if not references:
        return found
    folders = [LAB / 'logs', LAB / 'profiles' / profile / 'logs']
    for folder in folders:
        for name in ('errors.log.1', 'errors.log', 'agent.log.1', 'agent.log'):
            path = folder / name
            if not path.is_file():
                continue
            # Only exact diagnostic refs present in owning tool outcomes are selected.
            with path.open(errors='replace') as handle:
                for line in handle:
                    if 'kernel_upstream_failure' not in line or not any(r in line for r in references):
                        continue
                    value = outcome(line)
                    if not value or value.get('diagnostic_ref') not in references:
                        continue
                    ref = value['diagnostic_ref']
                    found[ref] = {'failure_kind': value.get('failure_kind'), 'operation': value.get('operation'),
                                  'transport_timeout': value.get('failure_kind') == 'timeout', 'private_source': str(path)}
    return found

rows = []
for assignment in sorted(campaign['rows'], key=lambda r: r['task']):
    if not assignment.get('run'):
        continue
    lane = REPO / assignment['lane']
    run = json.loads((lane / 'runs' / assignment['run'] / 'run.json').read_text())
    assert run['actor'] == assignment['actor'] and run.get('secondary') == assignment.get('secondary')
    users = {USERS[x] for x in run['testers']}
    roots = {(r['channel'], r['ts']) for r in run['roots']}
    for _ in range(8):
        before = set(roots)
        for transfer in transfers:
            if transfer['owner'] not in users or not transfer['source']:
                continue
            original, source = json.loads(transfer['original_source']), json.loads(transfer['source'])
            if (original.get('chat_id'), original.get('thread_id')) in roots:
                root = source.get('chat_id'), source.get('thread_id')
                if isinstance(root[0], str) and isinstance(root[1], str) and re.fullmatch(r'\d+\.\d+', root[1]):
                    roots.add(root)
        if roots == before:
            break
    low, high = float(run['started_at']), float(run.get('finished_at') or time.time())
    result = {'task': assignment['task'], 'run': run['id'], 'actor': run['actor'], 'root': run['roots'][0],
              'causal_roots': [{'channel': ch, 'ts': ts} for ch, ts in sorted(roots)],
              'closed': bool(run.get('finished_at')), 'window_start': low, 'window_end': high,
              'owning_traces': [], 'tool_results_scanned': 0, 'profile_busy_count': 0,
              'provider_transport_timeout_count': 0, 'other_timeout_failure_count': 0,
              'user_input_expiry_count': 0, 'unclassified_provider_failure_count': 0, 'events': [], 'gaps': []}
    seen = set()
    # Shared-channel runs and private handoffs have canonical task homes, not
    # necessarily the participant's ordinary DM profile. Query only exact
    # requester and causal-thread identities in each known Hermes database.
    for user, dbpath in ((user, path) for user in sorted(users) for path in DB_PATHS):
        profile = 'default' if dbpath.parent == LAB else dbpath.parent.name
        db = readonly(dbpath)
        for ch, ts in sorted(roots):
            sessions = db.execute('SELECT id,session_key FROM sessions WHERE source=? AND user_id=? AND chat_id=? AND thread_id=?',
                                  ('slack', user, ch, ts)).fetchall()
            for session in sessions:
                trace = {'profile': profile, 'requester': user, 'session_id': session['id'], 'chat_id': ch,
                         'thread_id': ts, 'private_source': str(dbpath), 'tool_results_scanned': 0}
                outcomes = db.execute('SELECT id,tool_name,content,timestamp FROM messages WHERE session_id=? AND role=? AND timestamp>=? AND timestamp<=? ORDER BY id',
                                      (session['id'], 'tool', low, high)).fetchall()
                prepared = []
                refs = set()
                for message in outcomes:
                    identity = (profile, session['id'], message['id'])
                    if identity in seen:
                        continue
                    seen.add(identity); trace['tool_results_scanned'] += 1; result['tool_results_scanned'] += 1
                    value = outcome(message['content']); text = error_text(value, message['content'])
                    references = set(re.findall(r'Reference:\s*([a-f0-9]{32})\b', text))
                    if value and re.fullmatch(r'[a-f0-9]{32}', str(value.get('diagnostic_ref', ''))):
                        references.add(value['diagnostic_ref'])
                    refs.update(references); prepared.append((message, text, references, identity))
                diagnostics = linked_diagnostics(profile, refs)
                for message, text, references, identity in prepared:
                    folded = text.lower()
                    busy = bool(re.search(r'\bProfileBusy\b', text)) or 'this browser profile is in use by another task or sign-in' in folded or 'requester profile is locked' in folded
                    input_expiry = 'awaiting_input_timeout' in folded or 'sign-in request expired' in folded
                    transport = not input_expiry and (bool(re.search(r'\b(?:ReadTimeout|ConnectTimeout)\b|requests\.exceptions\.Timeout\b|httpsconnectionpool[^\n]{0,300}timed out', text, re.I)) or any(diagnostics.get(ref, {}).get('transport_timeout') for ref in references))
                    other_timeout = not input_expiry and not transport and bool(re.search(r'\bTimeoutError\b|timed out|\btimeout\b', text, re.I))
                    unknown = bool(references - diagnostics.keys())
                    if not any((busy, transport, other_timeout, input_expiry, unknown)):
                        continue
                    identifier = hashlib.sha256(('|'.join(map(str, identity))).encode()).hexdigest()[:24]
                    event = {'id': identifier, 'tool': message['tool_name'], 'at': message['timestamp'],
                             'profile_busy': busy, 'provider_transport_timeout': transport,
                             'other_timeout_failure': other_timeout, 'user_input_expiry': input_expiry,
                             'unclassified_provider_failure': unknown,
                             'private_binding': {'profile': profile, 'session_id': session['id'], 'message_id': message['id']}}
                    result['events'].append(event)
                    for key, flag in [('profile_busy_count', busy), ('provider_transport_timeout_count', transport),
                                      ('other_timeout_failure_count', other_timeout), ('user_input_expiry_count', input_expiry),
                                      ('unclassified_provider_failure_count', unknown)]:
                        result[key] += int(flag)
                result['owning_traces'].append(trace)
        db.close()
    if not result['owning_traces']:
        result['gaps'].append('No exact requester-scoped Hermes session was found.')
    if result['unclassified_provider_failure_count']:
        result['gaps'].append('An exact provider failure reference had no matching diagnostic classification; transport count is incomplete.')
    rows.append(result)

counts = ('profile_busy_count', 'provider_transport_timeout_count', 'other_timeout_failure_count',
          'user_input_expiry_count', 'unclassified_provider_failure_count', 'tool_results_scanned')
output = {'campaign': CAMPAIGN, 'generated_at_utc': datetime.now(timezone.utc).isoformat(),
          'final': not args.pending, 'summary': {k: sum(r[k] for r in rows) for k in counts}, 'rows': rows,
          'method': 'Exact authenticated requester/channel/thread and durable causal-transfer bindings, constrained to each run lifetime. Failure events deduplicated by profile/session/message; owning diagnostics selected only by exact references from those outcomes.',
          'limits': ['Counts describe recorded tool failure outcomes, not arbitrary keyword mentions in page data or successful tools.',
                     'Transient provider retries that succeeded without a surfaced failure are outside these counts.',
                     'Human input expiry is separate from provider transport timeout.',
                     'Private tool, page, input, log and contact bodies are never retained.']}
target = BASE / ('runtime-flags-audit.pending.json' if args.pending else 'runtime-flags-audit.json')
temporary = target.with_suffix('.json.tmp')
temporary.write_text(json.dumps(output, indent=2) + '\n'); os.chmod(temporary, 0o600); temporary.replace(target)
print(json.dumps({'path': str(target), 'final': output['final'], 'runs': len(rows), 'summary': output['summary'], 'gaps': sum(bool(r['gaps']) for r in rows)}))

