text(await tools.exec_command({cmd:"python3 - <<'PY'
import pathlib,json,subprocess,hashlib,datetime,collections,concurrent.futures,math,os
repo=pathlib.Path('/Users/tanishqpalandurkar/Projects/yyot');base=repo/'.local/clanker-qa/batches/2026-10-12-corrected';public=repo/'assets/benchmark/2026-10-12-corrected/manifest.json';manifest=json.loads(public.read_text());private=json.loads((base/'replay-evidence.json').read_text());ledgers=repo/'.local/hermes-lab/home/.clanker-cloud/benchmark-capture'
assert manifest['campaign']=='2026-10-12-corrected'
private_by_id={r['replay_id']:r for r in private['entries']};gaps=[];ledger_cache={};entries=[]
fields='stream=index,codec_type,codec_name,width,height,pix_fmt,r_frame_rate,avg_frame_rate,time_base,duration,nb_frames,sample_rate,channels,channel_layout:format=format_name,start_time,duration,size'
def probe(r):
 p=(repo/r['file']).resolve();assert p.is_relative_to(repo/'assets/benchmark/2026-10-12-corrected')
 if not p.is_file():return r,None,None,'public_file_missing'
 sha=hashlib.sha256(p.read_bytes()).hexdigest()
 cmd=['ffprobe','-v','error','-show_entries',fields,'-of','json',str(p)]
 cp=subprocess.run(cmd,capture_output=True,text=True)
 if cp.returncode:return r,sha,None,'ffprobe_failed'
 return r,sha,json.loads(cp.stdout),None
with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:probes=list(pool.map(probe,manifest['replays']))
for index,(r,sha,media,err) in enumerate(probes):
 rid=r['replay_id'];sid=r['session_id'];mapping=[]
 if err:mapping.append(err)
 if sha!=r['sha256']:mapping.append('public_hash_mismatch')
